 *   int methodOne(int parameter) {
 *     if (parameter &lt;= 0 ) {
 *       throw new IllegalArgumentException("A positive value is expected");
 *     }
 *     parameter -= 2;  // violation
 *     return parameter;
 *   }
 *
 *   int methodTwo(int parameter) {
 *     if (parameter &lt;= 0 ) {
 *       throw new IllegalArgumentException("A positive value is expected");
