 *     int local = parameter;
 *     local -= 2;  // OK
 *     return local;
 *   }
 *
 *   IntPredicate obj = a -&gt; ++a == 12; // violation
 *   IntBinaryOperator obj2 = (int a, int b) -&gt; {
 *       a++;     // violation
 *       b += 12; // violation
 *       return a + b;
 *   };
 *   IntPredicate obj3 = a -&gt; {
 *       int b = a; // ok
 *       return ++b == 12;
 *   };
 * }
