        final int type = ast.getType();
        if (TokenUtil.isOfType(type, TokenTypes.CTOR_DEF, TokenTypes.METHOD_DEF)
                || type == TokenTypes.LAMBDA
                && ast.getParent().getType() != TokenTypes.SWITCH_RULE) {
            parameterNames = parameterNamesStack.pop();
