def refactor_code(file_paths, file_to_move, extracted_method_name):
    # Step 1: Find the file to move and the method to extract
    file_to_move = next((file for file in file_paths if file["name"] == file_to_move), None)
    if not file_to_move:
        return {}
    method_to_extract = next(
        (method for method in file_to_move["methods"] if method["name"] == extracted_method_name), None
    )
    if not method_to_extract:
        return {}

    # Step 2: Find a suitable target file for the moved method
    target_file = next(
        (file for file in file_paths if file["path"] != file_to_move["path"] and file["language"] == "java"), None
    )
    if not target_file:
        return {}

    # Step 3: Move the method to the target file
    target_file["methods"].append(method_to_extract)
    file_to_move["methods"].remove(method_to_extract)

    # Step 4: Update the method calls in the refactored class
    for file in file_paths:
        if file is not target_file and file is not file_to_move:
            for method in file["methods"]:
                if method["name"] == extracted_method_name:
                    method["body"] = f"{target_file['package']}.{target_file['name']}.{extracted_method_name}()"

    return {
        "target_file_path": target_file["path"],
        "extracted_method_code": method_to_extract["body"],
        "refactored_method_code": next(
            (method for method in file_to_move["methods"] if method["name"] == extracted_method_name), None
        )["body"],
    }
