def extract_method(class_content, method_code):
    class_name, method_name = method_code.split('.')
    if class_name not in class_content:
        return ''
    class_content = class_content[class_name]
    if method_name not in class_content:
        return ''
    method_content = class_content[method_name]
    return method_content
