        final String[] expected = {
            "12:5: " + getCheckMessage(MatchXpathCheck.MSG_KEY),
            "14:5: " + getCheckMessage(MatchXpathCheck.MSG_KEY),
        };
        verifyWithInlineConfigParser(
                getPath("InputMatchXpathBlockComments.java"), expected);
    }

