            .compile(".*//\\s*violation above,\\s.+\\s(?:['\"](.*)['\"])?$");

    /** A pattern to find the string: "// violation below, explanation". */
    private static final Pattern VIOLATION_BELOW_WITH_EXPLANATION_PATTERN = Pattern
